    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // Seed the contract with Ether so the rule is non-trivial.
        (bool seedOk, ) = address(c).call{value: amount}("");
        require(seedOk);

        uint priorBal = address(c).balance;
        uint ownerBalBefore = c.Owner().balance;

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The owner is this test contract (it deployed c), so the withdraw must succeed.
        // After it, the contract balance is zero and the owner received the whole prior balance.
        assert(!reverted && address(c).balance == 0 && c.Owner().balance == ownerBalBefore + priorBal);
    }

    receive() external payable {}
}

